import { describe, test, expect, vi } from 'vitest';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import {
  selectProductListCard,
  selectGalleryImages,
  selectSizeChipValues,
  resolveOrderableVariant,
} from './productListCardMapper';

const formatPrice = vi.fn((amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`);

const baseHit = {
  productId: 'prod-1',
  productName: 'Natura Mini Dress',
  price: 595,
  currency: 'USD',
  image: { link: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' },
};

describe('selectProductListCard', () => {
  test('returns null when the hit has no product name', () => {
    expect(selectProductListCard({ ...baseHit, productName: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when the hit has no usable image', () => {
    expect(selectProductListCard({ ...baseHit, image: undefined }, formatPrice)).toBeNull();
  });

  test('maps a real hit to plp ZimmProductCardProps', () => {
    const result = selectProductListCard(baseHit, formatPrice);
    expect(result).toEqual({
      id: 'prod-1',
      href: '/product/prod-1',
      name: 'Natura Mini Dress',
      headingLevel: 'h3',
      primaryImage: { src: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' },
      images: undefined,
      currentPrice: 'USD 595.00',
      originalPrice: undefined,
      isUnavailable: false,
      badge: undefined,
      variation: 'plp',
      sizeChipValues: [],
    });
  });

  test('uses disBaseLink over link when both are present', () => {
    const hit = { ...baseHit, image: { link: 'fallback.jpg', disBaseLink: 'preferred.jpg', alt: 'x' } };
    expect(selectProductListCard(hit, formatPrice)?.primaryImage.src).toBe('preferred.jpg');
  });

  // Changed 2026-09-08 (was/now pricing fix): `currentPrice` now comes from `getPriceData`, not
  // a direct read of `hit.price` — and base SFCC's own `findLowestPrice` (product-utils.js:280-
  // 281) deliberately resolves "no price found at all" to `0`, not `undefined` ("we re[s]et the
  // value to 0 as minPrice to be able to use this value on UI" — its own comment). So a hit with
  // no price and no tieredPrices renders "$0.00", not a blank price — confirmed by reading that
  // function directly, not assumed. This replaces the old premise (`hit.price` read directly,
  // `undefined` in → `undefined` out), which no longer describes what the code does.
  test('resolves to a real $0.00 (base SFCC behaviour), not undefined, when there is no price data at all', () => {
    const hit = { ...baseHit, price: undefined };
    expect(selectProductListCard(hit, formatPrice)?.currentPrice).toBe('USD 0.00');
  });

  test('marks isUnavailable true when orderable is false', () => {
    expect(selectProductListCard({ ...baseHit, orderable: false }, formatPrice)?.isUnavailable).toBe(true);
  });

  // Was/now pricing (2026-09-08 fix) — closes the previously-confirmed gap: `originalPrice` used
  // to be hardcoded `undefined` regardless of data. Both fixtures cross-check against a real,
  // independent `getPriceData` call, not a hand-picked expectation — same "G1" doctrine
  // `recentlyViewedFullHistoryCard.test.ts`'s own equivalent tests already document.
  describe('was/now pricing', () => {
    const ON_SALE_HIT = {
      ...baseHit,
      price: 500,
      tieredPrices: [
        { price: 500, quantity: 1 },
        { price: 650, quantity: 1 },
      ],
    };

    test('originalPrice is the real "was" price when the hit is genuinely on sale', () => {
      const independent = getPriceData(ON_SALE_HIT);
      expect(independent.isOnSale).toBe(true);

      const card = selectProductListCard(ON_SALE_HIT, formatPrice);
      expect(card?.currentPrice).toBe('USD 500.00');
      expect(card?.originalPrice).toBe('USD 650.00');
    });

    test('originalPrice stays undefined — never equal to currentPrice — when the hit is not on sale', () => {
      // Identical price/listPrice (both 595) -- getPriceData's isOnSale is `currentPrice < listPrice`,
      // false when they're equal. A not-on-sale hit must never render a crossed-out price
      // identical to its current one.
      const notOnSaleHit = { ...baseHit, tieredPrices: [{ price: 595, quantity: 1 }] };
      const independent = getPriceData(notOnSaleHit);
      expect(independent.isOnSale).toBe(false);

      const card = selectProductListCard(notOnSaleHit, formatPrice);
      expect(card?.originalPrice).toBeUndefined();
      expect(card?.currentPrice).toBe('USD 595.00');
    });
  });

  test('maps the single highest-priority badge when c_productBadges is present', () => {
    const hit = { ...baseHit, c_productBadges: [{ productBadge: 'Runway' }, { productBadge: 'New In' }] };
    expect(selectProductListCard(hit, formatPrice)?.badge).toBe('Runway');
  });

  test('leaves badge undefined when c_productBadges is absent', () => {
    expect(selectProductListCard(baseHit, formatPrice)?.badge).toBeUndefined();
  });
});

describe('resolveOrderableVariant (2026-09-08, Gap 3 fix: size-aware Add to Bag)', () => {
  const hitWithVariants = {
    ...baseHit,
    variants: [
      { productId: 'prod-1-S', price: 595, orderable: true, variationValues: { size: 'S' } },
      { productId: 'prod-1-M', price: 595, orderable: false, variationValues: { size: 'M' } },
      { productId: 'prod-1-L', price: 650, orderable: true, variationValues: { size: 'L' } },
    ],
  };

  test('resolves the real variant productId and price for the selected size', () => {
    expect(resolveOrderableVariant(hitWithVariants, 'L')).toEqual({
      productId: 'prod-1-L',
      price: 650,
      orderable: true,
    });
  });

  test('reports orderable: false for a genuinely unorderable size, rather than dropping it', () => {
    expect(resolveOrderableVariant(hitWithVariants, 'M')).toEqual({
      productId: 'prod-1-M',
      price: 595,
      orderable: false,
    });
  });

  test('returns null when the size value matches no real variant', () => {
    expect(resolveOrderableVariant(hitWithVariants, 'XL')).toBeNull();
  });

  test('returns null when the hit has no variants array at all', () => {
    expect(resolveOrderableVariant(baseHit, 'S')).toBeNull();
  });
});

describe('selectGalleryImages', () => {
  test('returns undefined when there are no image groups', () => {
    expect(selectGalleryImages({ ...baseHit, imageGroups: undefined })).toBeUndefined();
  });

  test('returns undefined when every group has only 1 image', () => {
    const hit = {
      ...baseHit,
      imageGroups: [
        { viewType: 'small', images: [{ link: 'a.jpg' }] },
        { viewType: 'swatch', images: [{ link: 'b.jpg' }] },
      ],
    };
    expect(selectGalleryImages(hit)).toBeUndefined();
  });

  test('picks the image group with the most images', () => {
    const hit = {
      ...baseHit,
      imageGroups: [
        { viewType: 'small', images: [{ link: 'a.jpg' }] },
        {
          viewType: 'large',
          images: [
            { link: 'b1.jpg', alt: 'front' },
            { link: 'b2.jpg', alt: 'back' },
          ],
        },
      ],
    };
    expect(selectGalleryImages(hit)).toEqual([
      { src: 'b1.jpg', alt: 'front' },
      { src: 'b2.jpg', alt: 'back' },
    ]);
  });
});

describe('selectSizeChipValues', () => {
  test('returns an empty array when there is no size variation attribute', () => {
    expect(selectSizeChipValues({ ...baseHit, variationAttributes: undefined })).toEqual([]);
  });

  test('maps size attribute values to chip values, disabled from orderable', () => {
    const hit = {
      ...baseHit,
      variationAttributes: [
        {
          id: 'size',
          name: 'Size',
          values: [
            { value: 'xs', name: 'XS', orderable: true },
            { value: 's', name: 'S', orderable: false },
          ],
        },
        { id: 'color', name: 'Colour', values: [{ value: 'black', name: 'Black', orderable: true }] },
      ],
    };
    expect(selectSizeChipValues(hit)).toEqual([
      { value: 'xs', label: 'XS', isDisabled: false },
      { value: 's', label: 'S', isDisabled: true },
    ]);
  });

  test('falls back to the raw value as label when name is missing', () => {
    const hit = {
      ...baseHit,
      variationAttributes: [{ id: 'size', values: [{ value: 'm', orderable: true }] }],
    };
    expect(selectSizeChipValues(hit)).toEqual([{ value: 'm', label: 'm', isDisabled: false }]);
  });
});

/**
 * Maps one Recently Viewed product to the FULL `ZimmProductCard` props Recently Viewed's Full
 * History page (SFCC-84) renders — badge, size chips, was/now pricing and a multi-image gallery,
 * i.e. the `plp` variation's already-shipped shape, not `recentlyViewedCard.ts`'s narrower
 * image-only rail shape (SFCC-83's `recentlyViewed` variation). Both mappers read the same
 * underlying input — a plain Commerce API `Product` from `recentlyViewedProductFetch.ts`'s own
 * `getProducts` call — but produce deliberately different output shapes for two deliberately
 * different surfaces; see that mapper's own docblock for the rail's narrower contract and why it
 * stops at image-only.
 *
 * Added per the build plan's B2 discussion (finding 41b): "reuse the rail's mapper" was the
 * original, incorrect assumption for this page — `recentlyViewedCard.ts` cannot produce this
 * shape by its own design (image-only, no price, no gallery), so a second, separate mapper is
 * required. Per Jasmijn's SFCC-84 comment, the Full History card's default state is "image, name,
 * badge, price (incl. was/now), and cart icon" — exactly the `plp` variation's shape, which is why
 * this mapper's output includes `headingLevel: 'h3'` and `variation: 'plp'` directly (unlike
 * `recentlyViewedCard.ts`'s `RecentlyViewedCard`, which deliberately excludes both as its rail
 * container's job) — mirroring `productListCardMapper.ts`'s own `ProductListCardResult`, which
 * bakes in the same two fields for the same reason: its output is meant to be spread straight
 * into `<ZimmProductCard>` with nothing left for a caller to add.
 *
 * Modelled on `recentlyViewedCard.ts`'s general style/docblock conventions (no React/react-intl
 * import, `formatPrice` injected as a parameter, same hard `null`-gate contract for a product
 * with no usable name/image) and on `overrides/app/pages/product-list/productListCardMapper.ts`
 * (the closest existing precedent producing this exact `plp`-variation output shape from a real
 * product). Ported, not imported, from both — a genuinely separate, self-contained module with
 * its own local type aliases, the same relationship `recentlyViewedCard.ts` already has to
 * `productListCardMapper.ts` (see that file's own docblock).
 *
 * **What's ported near-verbatim from `productListCardMapper.ts`, and what changed:**
 * `selectGalleryImages`/`selectSizeChipValues` are re-pointed at `product.imageGroups`/
 * `product.variationAttributes` directly (the plain `Product` shape) in place of a
 * `ProductSearchHit`'s own same-named fields — the underlying `ImageGroup`/`Image`/
 * `VariationAttribute` shapes are the same `commerce-sdk-isomorphic` types either way (confirmed
 * directly against `node_modules/commerce-sdk-isomorphic/lib/index.esm.d.ts`), so the
 * picking/mapping logic itself needed no change, only the input type.
 *
 * **Primary-image resolution is NOT ported from `productListCardMapper.ts`'s own
 * `toCardImage(hit.image)`** — a plain `getProducts` `Product` has no equivalent flat `image`
 * field; that is a Search-hit-only convenience field. Instead this mirrors `recentlyViewedCard.ts`
 * `selectPrimaryImage` (`viewType: 'medium'` `imageGroups` lookup, required non-empty `alt`) — the
 * already-established, correct approach for this exact input shape.
 *
 * **Price handling is deliberately NOT copied from `productListCardMapper.ts`.** That mapper reads
 * the flat `hit.price` field for `currentPrice` while leaving `originalPrice` unset entirely — had
 * it called `getPriceData(hit).listPrice` for `originalPrice` while keeping `hit.price` for
 * `currentPrice`, the two would risk disagreeing on a multi-variant product, since `getPriceData`
 * internally sources its own `currentPrice` from `findLowestPrice()`, not from a flat `price`
 * field. Both `currentPrice` and `originalPrice` here come from one `getPriceData(product)` call
 * (base SFCC, `node_modules/@salesforce/retail-react-app/app/utils/product-utils.js:123-170`,
 * confirmed by reading it directly) so the two halves can never disagree. `originalPrice` is only
 * ever set when that same call's `isOnSale` is `true` — a not-on-sale product must not render a
 * crossed-out price identical to its current one.
 *
 * **Badge — a real, found gap, not silently papered over.** `productListCardMapper.ts` reads
 * `hit.c_productBadges?.[0]?.productBadge` off a Search hit's custom index field. Checked directly
 * against `commerce-sdk-isomorphic`'s own type declaration for the plain `Product` shape
 * (`node_modules/commerce-sdk-isomorphic/lib/index.esm.d.ts:59783-59835`, the exact block backing
 * `ShopperProductsTypes.Product`): there is no typed `c_productBadges` field there — only a
 * generic `{[key: string]: any}` index signature, which would let `product.c_productBadges`
 * compile without error but proves nothing about whether the real `getProducts` endpoint (a
 * hydration endpoint, not the search-index endpoint `c_productBadges` is confirmed on) actually
 * populates this custom, index-only attribute. `recentlyViewedProductFetch.ts`'s own `getProducts`
 * call requests no expand parameter that obviously corresponds to custom attributes either.
 * Rather than read a field with no confirmed backing, `badge` is left `undefined` below — see that
 * assignment's own comment. This is a real, unresolved gap, not a design choice: if Full History
 * needs badges to actually render, confirming whether `getProducts` carries this field needs a
 * live check against a real badged product in a running environment, the same "verify in the
 * running app" caveat the build plan's own B2 discussion already states for was/now pricing.
 */
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { getPriceData, filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type {
  ZimmProductCardBaseProps,
  ZimmProductCardPlpVariation,
  ZimmProductCardImage,
} from '../components/ui-kits/organisms/zimmProductCard';
import type { ZimmSizeChipValue } from '../components/ui-kits/molecules/zimmSizeChipGroup';

/**
 * The real Commerce API `Product` this mapper reads — the same `ShopperProductsTypes.Product`
 * `recentlyViewedProductFetch.ts` produces and `recentlyViewedCard.ts` also consumes. Named
 * locally (rather than importing `RecentlyViewedProduct` from that sibling module) so this stays
 * a genuinely separate, self-contained module — matching how this whole file is itself "ported,
 * not imported" from its own two precedents.
 */
export type RecentlyViewedFullHistoryProduct = ShopperProductsTypes.Product;

/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl —
 *  same shape as `recentlyViewedCard.ts`'s own `FormatPrice`, redeclared locally for the same
 *  separate-module reason as `RecentlyViewedFullHistoryProduct` above. */
export type FormatPrice = (amount: number, currency: string) => string;

/**
 * The full `plp`-variation `ZimmProductCard` props this mapper produces — badge, size chips,
 * was/now pricing, multi-image gallery, heading level and variation all included. Mirrors
 * `productListCardMapper.ts`'s own `ProductListCardResult` (unexported from that file, so
 * redeclared here rather than imported) — this mapper's output is meant to be spread straight
 * into `<ZimmProductCard>` by its page container (SFCC-84's Full History page, not yet built)
 * with nothing left to add, the same convenience that shape already gives PLP's own page.
 */
export type RecentlyViewedFullHistoryCard = ZimmProductCardBaseProps & ZimmProductCardPlpVariation;

/** The correctly-sized product image view for the required `primaryImage` slot — same constant,
 *  same reasoning, as `recentlyViewedCard.ts`'s own `MEDIUM_VIEW_TYPE`: never serve an
 *  arbitrary-sized image at thumbnail size (AGENTS.md's image-sizing guidance). */
const MEDIUM_VIEW_TYPE = 'medium';

/** The variation-attribute id this mapper reads for size chips — named per conventions.md's
 *  no-magic-strings rule. `productListCardMapper.ts`'s own `selectSizeChipValues`, which this is
 *  ported from, uses the literal inline; named here instead since this is a fresh file. */
const SIZE_VARIATION_ATTRIBUTE_ID = 'size';

/**
 * `getPriceData`'s own return shape (base SFCC, `product-utils.js:123-170`, confirmed by reading
 * it directly), narrowed to the three fields this mapper reads. `@salesforce/retail-react-app`
 * ships no TypeScript types — this subpath falls through `overrides/app/types/vendor.d.ts`'s
 * catch-all `declare module '@salesforce/retail-react-app/*'`, a shorthand ambient module
 * declaration that types the whole module `any`, so `getPriceData`'s real return is implicitly
 * `any`. Declaring a local, narrow type for the fields actually read — rather than letting that
 * `any` propagate into this module's own types — matches `variantScopedPrice.ts`'s own
 * narrow-local-type pattern for the same untyped function (typescript.md's no-`any` rule). This
 * is a type annotation documenting an assumed shape, not a runtime guarantee: TypeScript allows
 * assigning `any` to any narrower type with no check, so the real correctness proof is the test
 * file's own direct comparison against a real `getPriceData` call, not this annotation alone.
 */
type SfccPriceData = {
  /** `findLowestPrice()`'s own `minPrice` — never `product.price` directly. This is the field
   *  `productListCardMapper.ts` does not use for its own `currentPrice` (it reads the flat
   *  `hit.price` field instead) — see this module's own docblock for why that risks disagreeing
   *  with a `getPriceData`-derived `originalPrice` on a multi-variant product. */
  currentPrice: number;
  /** The highest tiered price found — "was" price. `undefined` when the product has no
   *  `tieredPrices` at all (there is then no maximum to compute). */
  listPrice: number | undefined;
  /** `currentPrice < listPrice` — always `false`, never `true`, when `listPrice` is `undefined`
   *  (a numeric comparison against `undefined` evaluates to `false` in JS, never throws). */
  isOnSale: boolean;
};

/** The real `imageGroups[].images[]` element shape (`commerce-sdk-isomorphic`'s own
 *  `ShopperProductsTypes.Image`) — named `RawImage` to match `productListCardMapper.ts`'s own
 *  local name for the equivalent concept, but pointed at the real SDK type rather than that
 *  file's hand-rolled shape (AGENTS.md > Type Definitions: don't re-declare a type the SDK
 *  already exports). */
type RawImage = ShopperProductsTypes.Image;

const toCardImage = (image: RawImage | undefined, productName: string): ZimmProductCardImage | undefined => {
  const src = image?.disBaseLink ?? image?.link;
  const alt = image?.alt?.trim() || productName.trim();
  if (!src || !alt) return undefined;
  return { src, alt };
};

/**
 * Picks the image group with the most images as this product's gallery. Ported near-verbatim from
 * `productListCardMapper.ts`'s own `selectGalleryImages` — viewpoint-agnostic on purpose, for the
 * same reason that file states: this catalog's real `viewType` naming was not confirmed for that
 * quick-test integration, so "most images" is used as a simple, real-data-driven proxy for "the
 * full gallery" rather than guessing a specific viewType string. Re-pointed at
 * `product.imageGroups` (the plain `getProducts` shape) in place of a `ProductSearchHit`'s own
 * same-named field — the underlying `ImageGroup`/`Image` types are identical either way, so only
 * the input type annotation changed. Returns `undefined` for 0 or 1 resulting images, matching
 * `ZimmProductCardMedia`'s own "no gallery" contract for that case.
 */
export const selectGalleryImages = (product: RecentlyViewedFullHistoryProduct): ZimmProductCardImage[] | undefined => {
  const groups = product.imageGroups ?? [];
  if (groups.length === 0) return undefined;

  const largest = groups.reduce((best, group) =>
    (group.images?.length ?? 0) > (best.images?.length ?? 0) ? group : best,
  );
  const images = (largest.images ?? [])
    .map((image) => toCardImage(image, product.name ?? ''))
    .filter((img): img is ZimmProductCardImage => Boolean(img));

  return images.length > 1 ? images : undefined;
};

/**
 * Resolves the required `primaryImage` slot. Not ported from `productListCardMapper.ts`'s own
 * `toCardImage(hit.image)` — a plain `getProducts` `Product` carries no equivalent flat `image`
 * field, that's a Search-hit-only convenience. Mirrors `recentlyViewedCard.ts`'s own
 * `selectPrimaryImage` instead: `viewType: 'medium'` (a real, correctly-sized product image),
 * first matching group, first image, required non-empty `alt` (falls back to the product name) —
 * the already-established, correct approach for this exact input shape. `ZimmProductCardMedia`
 * ignores `primaryImage` entirely whenever `images` carries more than one entry (confirmed
 * directly in that component's own source — `slideImages = gallery ?? [primaryImage]`), so this
 * value never conflicts with `selectGalleryImages`'s independent, viewpoint-agnostic pick above
 * even on the rare product where the two would otherwise disagree on which image comes first.
 *
 * **Also returns `fallbacks` (2026-09-08, live defect)** — see `recentlyViewedCard.ts`'s own
 * `selectPrimaryImage` for the full story (confirmed live against product `4673TS251`: a real
 * catalog image group can have a broken image ahead of working ones). Only actually matters for
 * a product with no multi-image `selectGalleryImages` result above (0 or 1 images in the `large`
 * group) — `ZimmProductCardMedia` ignores `primaryImage`/`primaryImageFallbacks` entirely once a
 * real gallery is active, per this file's own docblock two paragraphs up.
 *
 * @returns `null` when there is no usable `src` — `ZimmProductCardMediaImage.alt` is required and
 *   non-empty, so there is no safe placeholder card to build without a real image, the same
 *   hard-gate contract `recentlyViewedCard.ts`'s own `selectPrimaryImage` documents.
 */
const selectPrimaryImage = (
  product: RecentlyViewedFullHistoryProduct,
  productName: string,
): { image: ZimmProductCardImage; fallbacks: ZimmProductCardImage[] } | null => {
  const filteredGroups = filterImageGroups(product.imageGroups ?? [], {
    viewType: MEDIUM_VIEW_TYPE,
    variationValues: {},
  }) as ShopperProductsTypes.ImageGroup[];
  const groupImages = filteredGroups[0]?.images ?? [];
  const [groupImage, ...remainingGroupImages] = groupImages;
  if (!groupImage) return null;

  const src = groupImage.disBaseLink || groupImage.link;
  if (!src) return null;

  const alt = groupImage.alt?.trim() || productName;
  const fallbacks = remainingGroupImages
    .map((fallbackImage) => {
      const fallbackSrc = fallbackImage.disBaseLink || fallbackImage.link;
      if (!fallbackSrc) return null;
      return { src: fallbackSrc, alt: fallbackImage.alt?.trim() || productName };
    })
    .filter((fallbackImage): fallbackImage is ZimmProductCardImage => Boolean(fallbackImage));

  return { image: { src, alt }, fallbacks };
};

/**
 * Reads the "size" variation attribute (if this product has one) into the shape
 * `ZimmSizeChipGroup` expects. Ported near-verbatim from `productListCardMapper.ts`'s own
 * `selectSizeChipValues`, re-pointed at `product.variationAttributes` directly — `orderable` on
 * each value already reflects real stock for that specific size, so it maps directly to
 * `isDisabled` with no extra lookup needed.
 */
export const selectSizeChipValues = (product: RecentlyViewedFullHistoryProduct): ZimmSizeChipValue[] => {
  const sizeAttribute = product.variationAttributes?.find((attr) => attr.id === SIZE_VARIATION_ATTRIBUTE_ID);
  return (sizeAttribute?.values ?? []).map((value) => ({
    value: value.value,
    label: value.name ?? value.value,
    isDisabled: value.orderable === false,
  }));
};

/**
 * Derives `currentPrice`/`originalPrice` from a single `getPriceData(product)` call — see this
 * module's own docblock for why both must come from the same call rather than mixing a flat
 * `product.price` field for one and `getPriceData` for the other. No `opts` passed — the default
 * `quantity: 1` is correct for a single-unit card display (matches `variantScopedPrice.ts`'s own
 * no-opts calls for the same reason). No hardcoded fallback currency — if either the price or the
 * currency is absent, formatting is skipped rather than guessed, matching `productInfo.ts`'s and
 * `recentlyViewedCard.ts`'s own "no hardcoded fallback currency" rule.
 */
const selectPriceFields = (
  product: RecentlyViewedFullHistoryProduct,
  formatPrice: FormatPrice,
): Pick<RecentlyViewedFullHistoryCard, 'currentPrice' | 'originalPrice'> => {
  const priceData: SfccPriceData = getPriceData(product);

  const currentPrice =
    typeof priceData.currentPrice === 'number' && product.currency
      ? formatPrice(priceData.currentPrice, product.currency)
      : undefined;

  // Only set when isOnSale is true -- a not-on-sale product must not render a crossed-out price
  // identical to its current one.
  const originalPrice =
    priceData.isOnSale && typeof priceData.listPrice === 'number' && product.currency
      ? formatPrice(priceData.listPrice, product.currency)
      : undefined;

  return { currentPrice, originalPrice };
};

/**
 * @param product - A plain Commerce API product from `recentlyViewedProductFetch.ts`'s own
 *   `getProducts` call, or `undefined`/`null` while that data is not yet available.
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the `plp`-variation `ZimmProductCard`, or `null` when the product has no
 *   usable name or no usable image — never a broken card, never a throw. Same hard-gate contract
 *   as `recentlyViewedCard.ts`'s own `selectRecentlyViewedCard`.
 */
export const selectRecentlyViewedFullHistoryCard = (
  product: RecentlyViewedFullHistoryProduct | undefined | null,
  formatPrice: FormatPrice,
): RecentlyViewedFullHistoryCard | null => {
  if (!product?.name) return null;

  const selectedImage = selectPrimaryImage(product, product.name);
  if (!selectedImage) return null;

  const { currentPrice, originalPrice } = selectPriceFields(product, formatPrice);

  return {
    id: product.id,
    href: productUrlBuilder({ id: product.id }),
    name: product.name,
    headingLevel: 'h3',
    primaryImage: selectedImage.image,
    primaryImageFallbacks: selectedImage.fallbacks,
    images: selectGalleryImages(product),
    currentPrice,
    originalPrice,
    // Real, found gap -- see this module's own docblock's "Badge" section. ShopperProductsTypes.
    // Product carries no typed c_productBadges field, and there is no confirmation the plain
    // getProducts endpoint (as opposed to Product Search) populates this custom, index-only
    // attribute at all. Left unset rather than guessed at.
    badge: undefined,
    variation: 'plp',
    sizeChipValues: selectSizeChipValues(product),
  };
};

/**
 * Maps one Recently Viewed product onto the subset of `ZimmProductCard` props the
 * `recentlyViewed` variation (SFCC-83) actually renders.
 *
 * **Input source revised 2026-09-08 (build plan §2, "Interim data source") — Einstein is "Not
 * Deployed" on every real Zimmermann site, so this build ships against a browser-tracked
 * view-history stand-in instead.** Input is now a plain Commerce API `Product`
 * (`commerce-sdk-isomorphic`'s `ShopperProductsTypes.Product`), exactly as returned by
 * `overrides/app/utils/recentlyViewedProductFetch.ts`'s own `getProducts` call (`expand: [
 * 'prices', 'promotions', 'images', 'variations']`, `allImages: true`, `perPricebook: true`) —
 * the same underlying Shopper Products shape the original Einstein-sourced design used, minus the
 * Einstein-specific `rec`/flat-`image` wrapper fields `fetchRecProductDetails`
 * (`@salesforce/retail-react-app/app/hooks/use-einstein.js:465-505`) used to bolt on. This
 * mapper's own output contract and scope (image-only, no gallery, no was/now pricing — A2's
 * `recentlyViewed` variation decision, unchanged) are unaffected; only the shape of what it reads
 * on the way in changed, and with it, `selectPrimaryImage`'s fallback below: there is no longer a
 * separate flat Einstein image to fall back to, so "the selected `imageGroups` image has no
 * usable `src`" and "there is no usable image at all" are now the same case.
 *
 * Modelled on `overrides/app/pages/product-detail/productInfo.ts` — no React/react-intl import,
 * `formatPrice` injected as a parameter so this module stays independently testable — and on the
 * general shape of `liveProductCardDemoMapper.ts` (`feature/zimmproductcard-live-demo`, not this
 * branch — read for its approach, not imported). Unlike that demo mapper, this is a production
 * path: real `commerce-sdk-isomorphic` SDK types are used directly (AGENTS.md > Type
 * Definitions) — with the Einstein-specific input shape gone, there is no longer any hand-rolled
 * field on the input type at all.
 *
 * Deliberately narrow scope, stated here rather than left as a silent gap: this mapper only ever
 * returns `currentPrice` (an active selling price), not was/now sale-price detection
 * (`originalPrice`) — but that is a scope choice, not a data limitation. **Correction
 * (2026-09-08, pre-dates and is unaffected by the input-source revision above):** an earlier
 * version of this comment claimed the merged Einstein shape "has no equivalent of"
 * `getPriceData`-style pricebook logic — verified inaccurate, and equally true of the plain
 * `getProducts` shape this mapper now reads: `recentlyViewedProductFetch.ts` already requests
 * `perPricebook: true`, so `product.tieredPrices` is present, and base SFCC's `getPriceData`
 * (`app/utils/product-utils.js`) already derives `listPrice`/`isOnSale` from exactly that field —
 * nothing is missing, it's simply not called here. The real reason `originalPrice` isn't mapped is
 * that the `recentlyViewed` variation renders no price at all today (see
 * `zimmProductCard/index.tsx`'s `recentlyViewed` `VARIATION_CONFIG` row — `showContent: false`), so
 * there is nothing for it to feed. Mapping `currentPrice` anyway costs nothing and means a future
 * consumer of this same mapper (e.g. a variation that does render price) isn't blocked on this
 * file being revisited — extending it to also call `getPriceData` at that point would be a small,
 * well-precedented addition, not new pricebook work.
 */
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type { ZimmProductCardBaseProps, ZimmProductCardImage } from '../components/ui-kits/organisms/zimmProductCard';

/**
 * The real Commerce API `Product` (`commerce-sdk-isomorphic`'s own `ShopperProductsTypes.Product`
 * — not hand-rolled). A plain alias, not an augmentation: unlike the pre-revision Einstein-sourced
 * shape this replaces, `recentlyViewedProductFetch.ts`'s plain `getProducts` result needs nothing
 * bolted on — `Product.id` is used directly, and there is no separate flat-image field. Kept as a
 * named alias (rather than importing `ShopperProductsTypes.Product` directly at each call site)
 * so this module's own input type has a name that documents its role here.
 */
export type RecentlyViewedProduct = ShopperProductsTypes.Product;

/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl,
 *  mirroring `productInfo.ts`'s own `FormatPrice` shape. */
export type FormatPrice = (amount: number, currency: string) => string;

/**
 * The subset of `ZimmProductCardBaseProps` this mapper populates. Deliberately excludes
 * `headingLevel` and `variation` — both are render-context decisions belonging to the container
 * step that maps recs through this mapper and renders the rail (SFCC-83's A6 step), which supplies
 * `headingLevel` uniformly for every card and adds `variation: 'recentlyViewed'` itself when
 * spreading this output into `<ZimmProductCard>` — the rail organism itself (A5) takes already-full
 * `ZimmProductCardProps` objects, so variation must already be set before it sees them. A pure data
 * mapper choosing a heading level would conflate a data concern with a layout one. Also excludes `hoverImage`/`images` — this
 * mapper only ever returns one image (`primaryImage`); see `selectPrimaryImage`'s own docblock
 * for why.
 */
export type RecentlyViewedCard = Pick<
  ZimmProductCardBaseProps,
  'id' | 'href' | 'name' | 'primaryImage' | 'primaryImageFallbacks' | 'currentPrice'
>;

/** The correctly-sized product image view, per AGENTS.md's image-sizing guidance: never serve an
 *  arbitrary-sized image at thumbnail size. Named rather than inlined per conventions.md's
 *  no-magic-strings rule — this is a real, semantic SFCC image `viewType` key. */
const MEDIUM_VIEW_TYPE = 'medium';

/**
 * Resolves the one image this mapper ever returns. `hoverImage`/`images` are never populated —
 * SFCC-83 AC 3 asks for "the product's index image" (singular), and the `recentlyViewed`
 * variation renders neither a hover-swap nor a gallery (see `zimmProductCard/index.tsx`'s
 * `recentlyViewed` row: `showHoverImageSwap: false`, and its render branch never forwards
 * `images` at all).
 *
 * Uses `filterImageGroups` at `viewType: 'medium'` (a real, correctly-sized product image) —
 * `variationValues` is deliberately empty: a Recently Viewed product is already one specific
 * product, not a search hit needing a variant pick the way `liveProductCardDemoMapper.ts`'s own
 * `resolveDemoVariant` handles, so that logic does not apply here.
 *
 * **No flat-image fallback (2026-09-08 input-source revision).** The pre-revision Einstein-merged
 * shape carried its own flat `image.disBaseLink`/`image.alt` (Einstein's own single-reference
 * thumbnail) to fall back to when `imageGroups` filtering came up empty. The plain
 * `getProducts` shape this mapper now reads has no equivalent field at all — `imageGroups` is the
 * only image source there is — so "the selected `imageGroups` image has no usable `src`" and
 * "there is no usable image at all" have collapsed into the same case; both now return `null`.
 *
 * **Also returns `fallbacks` — the rest of the same matched image group (2026-09-08, live
 * defect).** Confirmed live against product `4673TS251`: its `medium` group has 9 real images,
 * but index 0 specifically 404s (a stale/unpublished catalog image reference) while the other 8
 * resolve fine — `filterImageGroups`/`[0]` alone had no way to route around a single bad entry
 * sitting ahead of good ones in the same group. `fallbacks` is every OTHER image in that same
 * matched group, in order, for `ZimmProductCardMedia`'s own cascading `primaryImageFallbacks`
 * prop to try if the chosen primary image fails to load — see that component's own JSDoc for the
 * full mechanism. Not a new image *source*, just no longer silently discarding the 8 working
 * images that were already sitting right next to the one broken one.
 *
 * @returns `null` when there is no usable `src`. `ZimmProductCardMediaImage.alt` is required and
 *   non-empty, so there is no safe placeholder card to build without a real image — "no usable
 *   image" is treated the same as "no usable name" in `selectRecentlyViewedCard` below: a hard
 *   gate that yields no card at all. Returning `null` here is the only option that structurally
 *   cannot violate the non-empty-`alt` contract, since there is no returned object for `alt` to
 *   be empty on.
 */
const selectPrimaryImage = (
  product: RecentlyViewedProduct,
  productName: string,
): { image: ZimmProductCardImage; fallbacks: ZimmProductCardImage[] } | null => {
  const filteredGroups = filterImageGroups(product.imageGroups ?? [], {
    viewType: MEDIUM_VIEW_TYPE,
    variationValues: {},
  }) as ShopperProductsTypes.ImageGroup[];
  const groupImages = filteredGroups[0]?.images ?? [];
  const [groupImage, ...remainingGroupImages] = groupImages;
  if (!groupImage) return null;

  const src = groupImage.disBaseLink || groupImage.link;
  if (!src) return null;

  // ZimmProductCardMediaImage.alt is required and non-empty (unlike base ProductTile's
  // decorative alt: '' convention) — mirrors liveProductCardDemoMapper.ts's own fallback exactly.
  const alt = groupImage.alt?.trim() || productName;
  const fallbacks = remainingGroupImages
    .map((fallbackImage) => {
      const fallbackSrc = fallbackImage.disBaseLink || fallbackImage.link;
      if (!fallbackSrc) return null;
      return { src: fallbackSrc, alt: fallbackImage.alt?.trim() || productName };
    })
    .filter((fallbackImage): fallbackImage is ZimmProductCardImage => Boolean(fallbackImage));

  return { image: { src, alt }, fallbacks };
};

/**
 * @param product - A plain Commerce API product from `recentlyViewedProductFetch.ts`'s own
 *   `getProducts` call, or `undefined`/`null` while that data is not yet available.
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the `recentlyViewed` `ZimmProductCard` variation, or `null` when the product
 *   has no usable name or no usable image — never a broken card, never a throw.
 */
export const selectRecentlyViewedCard = (
  product: RecentlyViewedProduct | undefined | null,
  formatPrice: FormatPrice,
): RecentlyViewedCard | null => {
  if (!product?.name) return null;

  const selectedImage = selectPrimaryImage(product, product.name);
  if (!selectedImage) return null;

  return {
    id: product.id,
    href: productUrlBuilder({ id: product.id }),
    name: product.name,
    primaryImage: selectedImage.image,
    primaryImageFallbacks: selectedImage.fallbacks,
    // No hardcoded fallback currency — if either is absent, skip formatting rather than guess,
    // matching productInfo.ts's own "no hardcoded fallback currency" comment.
    currentPrice:
      typeof product.price === 'number' && product.currency ? formatPrice(product.price, product.currency) : undefined,
  };
};

