1	import { describe, test, expect, vi } from 'vitest';
2	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
3	import {
4	  selectProductListCard,
5	  selectGalleryImages,
6	  selectSizeChipValues,
7	  resolveOrderableVariant,
8	  resolveRepresentativeColour,
9	} from './productListCardMapper';
10	
11	const formatPrice = vi.fn((amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`);
12	
13	const baseHit = {
14	  productId: 'prod-1',
15	  productName: 'Natura Mini Dress',
16	  price: 595,
17	  currency: 'USD',
18	  image: { link: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' },
19	};
20	
21	// Mirrors the confirmed live shape of a real 2-colour product (`ZWNEWPRD04`, colours BLK/TAN,
22	// each with its own separate, explicitly-tagged `imageGroups` entry at viewType: medium) --
23	// see productListCardMapper.ts's own `resolveRepresentativeColour`/`selectColourScopedImages`
24	// docblocks (plan addendum §7, step C1, 2026-09-09). BLK is deliberately rigged with MORE images
25	// than TAN even though TAN is the represented (correct) colour -- proving a test built on this
26	// fixture only passes because the fix reads representedProduct/variants, never because the
27	// "right" colour happens to also have the most images.
28	const MULTI_COLOUR_HIT = {
29	  ...baseHit,
30	  productId: 'ZWNEWPRD04',
31	  representedProduct: { id: 'ZWNEWPRD04TAN0' },
32	  variants: [
33	    { productId: 'ZWNEWPRD04BLK0', variationValues: { color: 'BLK' } },
34	    { productId: 'ZWNEWPRD04TAN0', variationValues: { color: 'TAN' } },
35	  ],
36	  imageGroups: [
37	    {
38	      viewType: 'medium',
39	      variationAttributes: [{ id: 'color', values: [{ value: 'BLK' }] }],
40	      images: [
41	        { link: 'blk-1.jpg', alt: 'WRONG COLOUR -- MUST NOT BE PICKED' },
42	        { link: 'blk-2.jpg', alt: 'WRONG COLOUR -- MUST NOT BE PICKED' },
43	        { link: 'blk-3.jpg', alt: 'WRONG COLOUR -- MUST NOT BE PICKED' },
44	        { link: 'blk-4.jpg', alt: 'WRONG COLOUR -- MUST NOT BE PICKED' },
45	      ],
46	    },
47	    {
48	      viewType: 'medium',
49	      variationAttributes: [{ id: 'color', values: [{ value: 'TAN' }] }],
50	      images: [
51	        { link: 'tan-1.jpg', alt: 'Cascade Midi Dress, Tan, front' },
52	        { link: 'tan-2.jpg', alt: 'Cascade Midi Dress, Tan, side' },
53	        { link: 'tan-3.jpg', alt: 'Cascade Midi Dress, Tan, back' },
54	      ],
55	    },
56	  ],
57	};
58	
59	describe('selectProductListCard', () => {
60	  test('returns null when the hit has no product name', () => {
61	    expect(selectProductListCard({ ...baseHit, productName: undefined }, formatPrice)).toBeNull();
62	  });
63	
64	  test('returns null when the hit has no usable image', () => {
65	    expect(selectProductListCard({ ...baseHit, image: undefined }, formatPrice)).toBeNull();
66	  });
67	
68	  test('maps a real hit to plp ZimmProductCardProps', () => {
69	    const result = selectProductListCard(baseHit, formatPrice);
70	    expect(result).toEqual({
71	      id: 'prod-1',
72	      href: '/product/prod-1',
73	      name: 'Natura Mini Dress',
74	      headingLevel: 'h3',
75	      primaryImage: { src: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' },
76	      // baseHit has no imageGroups at all, so the colour+viewType-scoped array is empty --
77	      // hoverImage/primaryImageFallbacks gracefully absent, same as images (2026-09-09 addendum).
78	      hoverImage: undefined,
79	      primaryImageFallbacks: [],
80	      images: undefined,
81	      currentPrice: 'USD 595.00',
82	      originalPrice: undefined,
83	      isUnavailable: false,
84	      badge: undefined,
85	      variation: 'plp',
86	      sizeChipValues: [],
87	    });
88	  });
89	
90	  test('uses disBaseLink over link when both are present', () => {
91	    const hit = { ...baseHit, image: { link: 'fallback.jpg', disBaseLink: 'preferred.jpg', alt: 'x' } };
92	    expect(selectProductListCard(hit, formatPrice)?.primaryImage.src).toBe('preferred.jpg');
93	  });
94	
95	  // Changed 2026-09-08 (was/now pricing fix): `currentPrice` now comes from `getPriceData`, not
96	  // a direct read of `hit.price` — and base SFCC's own `findLowestPrice` (product-utils.js:280-
97	  // 281) deliberately resolves "no price found at all" to `0`, not `undefined` ("we re[s]et the
98	  // value to 0 as minPrice to be able to use this value on UI" — its own comment). So a hit with
99	  // no price and no tieredPrices renders "$0.00", not a blank price — confirmed by reading that
100	  // function directly, not assumed. This replaces the old premise (`hit.price` read directly,
